package com.smartcanteen.controller;
import com.smartcanteen.entity.*;import com.smartcanteen.repository.*;import com.smartcanteen.service.CurrentUser;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.BigDecimal;import java.util.*;
@RestController @RequestMapping("/api") public class OrderController {private final OrderRepository orders;private final FoodItemRepository foods;private final CurrentUser current;public OrderController(OrderRepository o,FoodItemRepository f,CurrentUser c){orders=o;foods=f;current=c;}
public record ItemRequest(@NotNull Long foodItemId,@Min(1) @Max(50) int quantity){} public record CreateRequest(@NotEmpty List<@Valid ItemRequest> items){} public record StatusRequest(@NotBlank String status){}
@PostMapping("/orders") @Transactional public CustomerOrder create(@Valid @RequestBody CreateRequest r){CustomerOrder o=new CustomerOrder();o.setUser(current.get());o.setOrderNumber("SC-"+UUID.randomUUID().toString().substring(0,8).toUpperCase());BigDecimal sum=BigDecimal.ZERO;for(ItemRequest x:r.items()){FoodItem f=foods.findById(x.foodItemId()).orElseThrow(()->new IllegalArgumentException("Food item not found."));if(!f.isAvailable())throw new IllegalArgumentException(f.getName()+" is sold out.");BigDecimal line=f.getPrice().multiply(BigDecimal.valueOf(x.quantity()));sum=sum.add(line);OrderItem i=new OrderItem();i.setFoodItem(f);i.setFoodNameSnapshot(f.getName());i.setUnitPrice(f.getPrice());i.setQuantity(x.quantity());i.setLineTotal(line);o.addItem(i);}o.setSubtotal(sum);o.setTotalAmount(sum);o.setPaymentStatus(PaymentStatus.PENDING);o.setOrderStatus(OrderStatus.ORDER_PLACED);return orders.save(o);}
@GetMapping("/orders/my") public List<CustomerOrder> mine(){return orders.findByUserIdOrderByCreatedAtDesc(current.get().getId());}
@GetMapping("/orders/{id}") public CustomerOrder mineById(@PathVariable Long id){return orders.findByIdAndUserId(id,current.get().getId()).orElseThrow(()->new IllegalArgumentException("Order not found."));}
@GetMapping("/admin/orders")
public List<CustomerOrder> all() {
    return orders.findAllWithItemsOrderByCreatedAtDesc();
}
@GetMapping("/admin/orders/{id}") public CustomerOrder adminGet(@PathVariable Long id){return orders.findById(id).orElseThrow(()->new IllegalArgumentException("Order not found."));}
@PatchMapping("/admin/orders/{id}/status") @Transactional public CustomerOrder status(@PathVariable Long id,@Valid @RequestBody StatusRequest r){CustomerOrder o=orders.findById(id).orElseThrow();OrderStatus next;try{next=OrderStatus.valueOf(r.status().trim().toUpperCase().replace(' ','_'));}catch(Exception e){throw new IllegalArgumentException("Unknown order status.");}if(o.getPaymentStatus()!=PaymentStatus.PAID&&next!=OrderStatus.CANCELLED)throw new IllegalArgumentException("Only paid orders can be prepared.");boolean ok=switch(o.getOrderStatus()){case ORDER_PLACED,PAYMENT_CONFIRMED->next==OrderStatus.PREPARING||next==OrderStatus.CANCELLED;case PREPARING->next==OrderStatus.READY_FOR_PICKUP||next==OrderStatus.CANCELLED;case READY_FOR_PICKUP->next==OrderStatus.COMPLETED;case COMPLETED,CANCELLED->false;};if(!ok)throw new IllegalArgumentException("Invalid order status transition.");o.setOrderStatus(next);return orders.save(o);}
@GetMapping("/admin/dashboard/summary") public Map<String,Object> summary(){List<CustomerOrder> all=orders.findAll();BigDecimal sales=all.stream().filter(o->o.getOrderStatus()==OrderStatus.COMPLETED&&o.getPaymentStatus()==PaymentStatus.PAID).map(CustomerOrder::getTotalAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("totalOrders",all.size(),"pendingOrders",all.stream().filter(o->o.getOrderStatus()==OrderStatus.ORDER_PLACED).count(),"preparingOrders",all.stream().filter(o->o.getOrderStatus()==OrderStatus.PREPARING).count(),"completedOrders",all.stream().filter(o->o.getOrderStatus()==OrderStatus.COMPLETED).count(),"totalSales",sales);}}
